package donut

import (
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// End-to-end: the library's public Build API produces shellcode, and standalone
// loaders (a plain C executable and a Python ctypes script) run it. This proves
// the generated bytes are usable outside the Go harness entirely.

func libgen(t *testing.T, vdir, pe, out, arch, method string, entropy, compress int) {
	t.Helper()
	args := []string{"-in", filepath.Join(vdir, pe), "-out", filepath.Join(vdir, out),
		"-arch", arch, "-method", method, "-entropy", itoa(entropy), "-compress", itoa(compress)}
	outb, code := runCmd(t, filepath.Join(vdir, "libgen.exe"), args...)
	if code != 0 {
		t.Fatalf("libgen failed (%d): %s", code, outb)
	}
}

func itoa(n int) string {
	if n == 0 {
		return "0"
	}
	neg := n < 0
	if neg {
		n = -n
	}
	var b [20]byte
	i := len(b)
	for n > 0 {
		i--
		b[i] = byte('0' + n%10)
		n /= 10
	}
	if neg {
		i--
		b[i] = '-'
	}
	return string(b[i:])
}

func TestE2E_CLoader(t *testing.T) {
	wd, _ := os.Getwd()
	vdir := filepath.Join(wd, "verify")
	for _, f := range []string{"libgen.exe", "cloader64.exe", "cloader32.exe",
		"payload_dll64.dll", "payload_dll32.dll", "payload_exe64.exe", "payload_noentry64.dll"} {
		if _, err := os.Stat(filepath.Join(vdir, f)); err != nil {
			t.Skipf("artefact %s missing; run verify/build.ps1", f)
		}
	}
	cases := []struct {
		name, pe, arch, method, loader, want string
		entropy, compress                   int
	}{
		{"dll_x64", "payload_dll64.dll", "x64", "RunIt", "cloader64.exe", "PAYLOAD_DLL run sum=5050", 1, 1},
		{"dll_x64_enc", "payload_dll64.dll", "x64", "RunIt", "cloader64.exe", "PAYLOAD_DLL run sum=5050", 3, 1},
		{"dll_x64_aplib", "payload_dll64.dll", "x64", "RunIt", "cloader64.exe", "PAYLOAD_DLL run sum=5050", 1, 2},
		{"dll_x64_lznt1", "payload_dll64.dll", "x64", "RunIt", "cloader64.exe", "PAYLOAD_DLL run sum=5050", 1, 3},
		{"dll_x64_xpress", "payload_dll64.dll", "x64", "RunIt", "cloader64.exe", "PAYLOAD_DLL run sum=5050", 1, 4},
		{"noentry_x64", "payload_noentry64.dll", "x64", "RunIt", "cloader64.exe", "PAYLOAD_NOENTRY run", 1, 1},
		{"exe_x64", "payload_exe64.exe", "x64", "", "cloader64.exe", "PAYLOAD_EXE sum=5050", 1, 1},
		{"dll_x86", "payload_dll32.dll", "x86", "RunIt", "cloader32.exe", "PAYLOAD_DLL run sum=5050", 1, 1},
		{"dll_x86_aplib", "payload_dll32.dll", "x86", "RunIt", "cloader32.exe", "PAYLOAD_DLL run sum=5050", 1, 2},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			bin := "e2e_c_" + tc.name + ".bin"
			libgen(t, vdir, tc.pe, bin, tc.arch, tc.method, tc.entropy, tc.compress)
			out, code := runCmd(t, filepath.Join(vdir, tc.loader), filepath.Join(vdir, bin))
			if !strings.Contains(out, tc.want) {
				t.Fatalf("C loader missing marker %q (exit=%d):\n%s", tc.want, code, out)
			}
			// DLLs return to the loader; EXEs terminate the process via CRT exit.
			if strings.HasPrefix(tc.pe, "payload_dll") || strings.HasPrefix(tc.pe, "payload_noentry") {
				if !strings.Contains(out, "CLOADER_RETURNED") {
					t.Fatalf("C loader should return after DLL; out:\n%s", out)
				}
			}
		})
	}
}

func TestE2E_PythonLoader(t *testing.T) {
	wd, _ := os.Getwd()
	vdir := filepath.Join(wd, "verify")
	for _, f := range []string{"libgen.exe", "pyloader.py", "payload_dll64.dll", "payload_noentry64.dll"} {
		if _, err := os.Stat(filepath.Join(vdir, f)); err != nil {
			t.Skipf("artefact %s missing; run verify/build.ps1", f)
		}
	}
	py, err := exec.LookPath("python")
	if err != nil {
		t.Skip("python not on PATH")
	}
	// Python must be 64-bit to host x64 shellcode.
	bits, _ := runCmd(t, py, "-c", "import struct;print(struct.calcsize('P')*8)")
	if strings.TrimSpace(bits) != "64" {
		t.Skipf("python is %s-bit; need 64-bit for x64 shellcode", strings.TrimSpace(bits))
	}
	cases := []struct {
		name, pe, method, want string
		entropy                int
	}{
		{"dll_x64", "payload_dll64.dll", "RunIt", "PAYLOAD_DLL run sum=5050", 1},
		{"dll_x64_enc", "payload_dll64.dll", "RunIt", "PAYLOAD_DLL run sum=5050", 3},
		{"noentry_x64", "payload_noentry64.dll", "RunIt", "PAYLOAD_NOENTRY run", 1},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			bin := "e2e_py_" + tc.name + ".bin"
			libgen(t, vdir, tc.pe, bin, "x64", tc.method, tc.entropy, 1)
			out, code := runCmd(t, py, filepath.Join(vdir, "pyloader.py"), filepath.Join(vdir, bin))
			if code != 0 || !strings.Contains(out, tc.want) {
				t.Fatalf("Python loader missing marker %q (exit=%d):\n%s", tc.want, code, out)
			}
			if !strings.Contains(out, "PYLOADER_RETURNED") {
				t.Fatalf("Python loader should return after DLL; out:\n%s", out)
			}
		})
	}
}